import ru.morcool.sender.*;import java.util.*;import java.io.*;
public class CoreTest{
 static int count;static void check(boolean value,String why){count++;if(!value)throw new AssertionError(why);}static void reject(Runnable r){try{r.run();throw new AssertionError("Expected rejection");}catch(IllegalArgumentException ok){count++;}}
 public static void main(String[] args)throws Exception{
  check(Core.phone("8 (999) 123-45-67","7").equals("+79991234567"),"Russian trunk");check(Core.phone("9991234567","7").equals("+79991234567"),"local RU");check(Core.phone("+44 7700 900123","7").equals("+447700900123"),"international");check(Core.phone("00447700900123","7").equals("+447700900123"),"00 prefix");check(Core.phone("7700900123","44").equals("+447700900123"),"country choice");reject(()->Core.phone("12","7"));reject(()->Core.phone("+7999<script>","7"));reject(()->Core.phone("+0123456789","7"));
  List<List<String>> csv=Core.csv("\uFEFFphone;name;note\r\n+79991234567;\"Анна; Мария\";\"строка\nвторая\"\r\n");check(csv.size()==2,"records");check(csv.get(1).get(1).equals("Анна; Мария"),"quoted delimiter");check(csv.get(1).get(2).equals("строка\nвторая"),"multiline");check(Core.csv("phone,name\n123,\"A\"\"B\"").get(1).get(1).equals("A\"B"),"escaped quotes");check(Core.csv("phone\tname\n123\tАнна").get(1).size()==2,"Excel paste tabs");check(Core.csv("\"phone;number\",name\n123,X").get(1).size()==2,"delimiter ignored inside quote");reject(()->Core.csv("a,b\n\"unfinished"));reject(()->Core.csv("a,b\n\"closed\"x,c"));
  Map<String,String> fields=new HashMap<>();fields.put("name","{phone} $ "+(char)92);fields.put("phone","+79991234567");fields.put("Заказ","42");check(Core.render("{name} / {Заказ}",fields).equals("{phone} $ "+(char)92+" / 42"),"literal replacement and Cyrillic");reject(()->Core.render("{missing}",fields));reject(()->Core.render(" ",fields));check(Core.quote("abc").equals("\"abc\""),"CSV escaping");
  Sheets.Book b=Sheets.read(java.nio.file.Files.readAllBytes(java.nio.file.Paths.get(args[0])));check(b.names.size()==2,"two XLSX sheets");check(b.names.get(0).equals("Клиенты"),"sheet name");check(b.sheets.get(0).get(1).get(0).equals("79991234567"),"scientific phone");check(b.sheets.get(0).get(1).get(1).equals("Анна"),"shared strings");check(b.sheets.get(0).get(1).get(2).equals("42"),"inline string");check(b.sheets.get(1).get(0).size()==3,"sparse columns preserved");check(b.sheets.get(1).get(0).get(1).equals(""),"sparse empty column");
  System.out.println("PASS: "+count+" parser, template and XLSX cases");
 }
}
